public static void main(String[] args) {

	FastScanner sc = new FastScanner();
	PrintWriter out = new PrintWriter(System.out);

	int n = Integer.parseInt(sc.next());
	int m = Integer.parseInt(sc.next());
	long[][] a = new long[n][2];
	for (int i = 0; i < n; i++) {
		a[i][0] = Long.parseLong(sc.next()); // price
		a[i][1] = Long.parseLong(sc.next()); // candy count
	}
	Arrays.sort(a, (x, y) -> x[1] != y[1] ? Long.compare(x[1], y[1]) : Long.compare(x[0], y[0]));

	long[] b = new long[m];
	for (int i = 0; i < m; i++) {
		b[i] = Long.parseLong(sc.next());
	}
	Arrays.sort(b);

	PriorityQueue<Long> pq = new PriorityQueue<>();
	int j = 0;
	long ans = 0L;
	for (int i = 0; i < m; i++) {
		while (j < n && a[j][1] < b[i]) {
			j++;
		}
		while (j < n && a[j][1] >= b[i]) {
			pq.add(a[j][0]);
			j++;
		}
		if (pq.isEmpty()) {
			out.println(-1);
			out.flush();
			return;
		}
		ans += pq.poll();
	}
	out.println(ans);
	out.flush();
}
